import { getBase58Decoder, getBase64Encoder, getUtf8Decoder } from '@solana/kit'
import { useMobileWallet } from '@wallet-ui/react-native-kit'
import { createSIWSInput } from 'better-auth-solana/client'
import { useState } from 'react'

import { authClient } from '@/lib/auth-client'
import { queryClient } from '@/lib/orpc'

function extractErrorMessage(error: unknown): string {
  if (error instanceof Error) {
    return error.message
  }
  return String(error || 'Solana sign in failed')
}

export function useAuthWalletSignIn() {
  const { account, connect, signIn } = useMobileWallet()
  const [isLoading, setIsLoading] = useState(false)

  async function signInWithWallet() {
    setIsLoading(true)
    try {
      const activeAccount = account || (await connect())
      const address = activeAccount.address
      const nonceResult = await authClient.siws.nonce({
        walletAddress: address,
      })

      if (!nonceResult.data) {
        throw new Error(nonceResult.error?.message || 'Failed to get nonce')
      }

      const result = await signIn(
        createSIWSInput({
          address,
          challenge: nonceResult.data,
          statement: 'Sign in to Solana Mobile Monorepo',
        }),
      )
      const signatureBase64 = getUtf8Decoder().decode(result.signature)
      const signedMessageBase64 = getUtf8Decoder().decode(result.signedMessage)
      const signatureBase58 = getBase58Decoder().decode(
        getBase64Encoder().encode(signatureBase64),
      )
      const messageUtf8 = getUtf8Decoder().decode(
        getBase64Encoder().encode(signedMessageBase64),
      )
      const verifyResult = await authClient.siws.verify({
        message: messageUtf8,
        signature: signatureBase58,
        walletAddress: address,
      })

      if (!verifyResult.data) {
        throw new Error(verifyResult.error?.message || 'Verification failed')
      }

      queryClient.invalidateQueries()
      await authClient.getSession()
    } catch (error) {
      throw new Error(extractErrorMessage(error))
    } finally {
      setIsLoading(false)
    }
  }

  return {
    isLoading,
    signInWithWallet,
  }
}

import {
  appendTransactionMessageInstruction,
  assertIsTransactionWithBlockhashLifetime,
  createTransactionMessage,
  getSignatureFromTransaction,
  pipe,
  sendAndConfirmTransactionFactory,
  setTransactionMessageFeePayerSigner,
  setTransactionMessageLifetimeUsingBlockhash,
  signTransactionMessageWithSigners,
} from '@solana/kit'
import { useWalletAccountTransactionSigner } from '@solana/react'
import type { SolanaClient } from '@solana-mobile-monorepo/solana-client'
import { getAddMemoInstruction } from '@solana-program/memo'
import type { SolanaClusterId, UiWalletAccount } from '@wallet-ui/react'
import { LucideKey } from 'lucide-react'
import { type SyntheticEvent, useCallback, useMemo, useState } from 'react'

import { Button } from '@/components/ui/button'
import {
  Card,
  CardAction,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/components/ui/card'
import { Input } from '@/components/ui/input'
import { Spinner } from '@/components/ui/spinner'

import { getErrorMessage } from '../ui/solana-ui-error'

export function SolanaFeatureWalletSignTransaction({
  account,
  client,
  cluster,
  onError,
  onSuccess,
}: {
  account: UiWalletAccount
  client: SolanaClient
  cluster: SolanaClusterId
  onError(error: unknown): void
  onSuccess(signature: string | undefined): void
}) {
  const [isLoading, setIsLoading] = useState(false)
  const [text, setText] = useState('Hello Solana!')
  const transactionSigner = useWalletAccountTransactionSigner(account, cluster)
  const sendAndConfirmTransaction = useMemo(
    () => sendAndConfirmTransactionFactory(client),
    [client],
  )

  const signTransaction = useCallback(async () => {
    const { value: latestBlockhash } = await client.rpc
      .getLatestBlockhash({ commitment: 'confirmed' })
      .send()
    const message = pipe(
      createTransactionMessage({ version: 0 }),
      (transaction) =>
        setTransactionMessageFeePayerSigner(transactionSigner, transaction),
      (transaction) =>
        setTransactionMessageLifetimeUsingBlockhash(
          latestBlockhash,
          transaction,
        ),
      (transaction) =>
        appendTransactionMessageInstruction(
          getAddMemoInstruction({ memo: text }),
          transaction,
        ),
    )

    const transaction = await signTransactionMessageWithSigners(message)

    assertIsTransactionWithBlockhashLifetime(transaction)

    const signature = getSignatureFromTransaction(transaction)

    await sendAndConfirmTransaction(transaction, { commitment: 'confirmed' })

    if (!signature) {
      throw new Error()
    }

    return signature
  }, [client.rpc, sendAndConfirmTransaction, text, transactionSigner])

  return (
    <form
      onSubmit={async (event) => {
        event.preventDefault()
        setIsLoading(true)

        try {
          const signature = await signTransaction()
          onSuccess(signature)
        } catch (error) {
          onError(getErrorMessage(error, 'Unknown error occurred'))
        } finally {
          setIsLoading(false)
        }
      }}
    >
      <Card>
        <CardHeader>
          <CardTitle>Sign Transaction</CardTitle>
          <CardDescription>Sign a transaction with a memo text</CardDescription>
          <CardAction>
            <Button
              disabled={!text || isLoading}
              size="lg"
              type="submit"
              variant="outline"
            >
              {isLoading ? <Spinner /> : <LucideKey />}
              Sign Transaction
            </Button>
          </CardAction>
        </CardHeader>
        <CardContent className="space-y-4">
          <Input
            onChange={(event: SyntheticEvent<HTMLInputElement>) =>
              setText(event.currentTarget.value)
            }
            placeholder="Write a memo text to sign as a transaction"
            value={text}
          />
        </CardContent>
      </Card>
    </form>
  )
}
